#[derive(Debug, Clone, PartialEq)]
pub struct Page {
    pub index: u32,
    pub w: f64,
    pub h: f64,
    pub background: Option<u32>,
    pub show: bool,
    pub items: Vec<Item>,
    pub notes: Option<Notes>,
    pub stroke: Option<Stroke>,
    pub small: u8,
    pub word: u16,
    pub signed: i32,
    pub handle: u32,
    pub title: Option<Vec<u16>>,
    /// The producer's own section: another schema's message, opaque here.
    pub app: Vec<u8>,
    pub first_dash: Dash,
}

impl Page {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 200;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.bitmap(&[self.background.is_some(), self.show, self.notes.is_some(), self.stroke.is_some(), self.title.is_some()]);
        w.u32(self.index);
        w.f64(self.w);
        w.f64(self.h);
        if let Some(v) = self.background {
            w.u32(v);
        }
        w.len(self.items.len());
        for e0 in self.items.iter() {
            e0.encode(w);
        }
        if let Some(v) = &self.notes {
            v.encode(w);
        }
        if let Some(v) = &self.stroke {
            v.encode(w);
        }
        w.u8(self.small);
        w.u16(self.word);
        w.i32(self.signed);
        w.u32(self.handle);
        if let Some(v) = &self.title {
            w.utf16(v);
        }
        w.bytes(&self.app);
        self.first_dash.encode(w);
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let bm = r.bitmap(5)?;
        let f_index = r.u32()?;
        let f_w = r.f64()?;
        let f_h = r.f64()?;
        let f_background = if bit(bm, 0) { Some(r.ref_in(0, "sym")?) } else { None };
        let f_show = bit(bm, 1);
        let f_items = { let n = r.list_of::<Item>(8)?; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(Item::decode(r)?); } v };
        let f_notes = if bit(bm, 2) { Some(Notes::decode(r)?) } else { None };
        let f_stroke = if bit(bm, 3) { Some(Stroke::decode(r)?) } else { None };
        let f_small = r.u8()?;
        let f_word = r.u16()?;
        let f_signed = r.i32()?;
        let f_handle = r.u32()?;
        let f_title = if bit(bm, 4) { Some(r.utf16()?) } else { None };
        let f_app = r.bytes()?;
        let f_first_dash = Dash::decode(r)?;
        Ok(Self { index: f_index, w: f_w, h: f_h, background: f_background, show: f_show, items: f_items, notes: f_notes, stroke: f_stroke, small: f_small, word: f_word, signed: f_signed, handle: f_handle, title: f_title, app: f_app, first_dash: f_first_dash })
    }
}

/// The root of the display-list test messages.
#[derive(Debug, Clone, PartialEq)]
pub struct Frame {
    pub page: Page,
    pub group: Option<Group>,
}

impl Frame {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 208;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.bitmap(&[self.group.is_some()]);
        self.page.encode(w);
        if let Some(v) = &self.group {
            v.encode(w);
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let bm = r.bitmap(1)?;
        let f_page = Page::decode(r)?;
        let f_group = if bit(bm, 0) { Some(Group::decode(r)?) } else { None };
        Ok(Self { page: f_page, group: f_group })
    }
}

/// A second root: a command with a payload enum and no tables of its own.
#[derive(Debug, Clone, PartialEq)]
pub enum Cmd {
    Insert(Vec<u16>),
    Delete(Span),
    Batch(Vec<Cmd>),
    Undo,
}

impl Cmd {
    /// The least number of bits a value takes on the wire.
    pub const MIN_BITS: u64 = 8;

    pub fn encode(&self, w: &mut Writer<'_>) {
        match self {
            Self::Insert(v) => {
                w.u32(0);
                w.utf16(v);
            }
            Self::Delete(v) => {
                w.u32(1);
                v.encode(w);
            }
            Self::Batch(v) => {
                w.u32(2);
                w.len(v.len());
                for e0 in v.iter() {
                    e0.encode(w);
                }
            }
            Self::Undo => w.u32(3),
        }
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        r.enter()?;
        let tag = r.u32()?;
        let value = match tag {
            0 => Self::Insert(r.utf16()?),
            1 => Self::Delete(Span::decode(r)?),
            2 => Self::Batch({ let n = r.list_of::<Cmd>(8)?; let mut v = Vec::with_capacity(n); for _ in 0..n { v.push(Cmd::decode(r)?); } v }),
            3 => Self::Undo,
            _ => return Err(DecodeError::BadTag { ty: "Cmd", tag }),
        };
        r.leave();
        Ok(value)
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Span {
    pub from: u32,
    pub to: u32,
}

impl Span {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 16;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.u32(self.from);
        w.u32(self.to);
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let f_from = r.u32()?;
        let f_to = r.u32()?;
        Ok(Self { from: f_from, to: f_to })
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Command {
    pub id: u32,
    pub cmd: Cmd,
}

impl Command {
    /// The least number of bits an element takes on the wire.
    pub const MIN_BITS: u64 = 16;

    pub fn encode(&self, w: &mut Writer<'_>) {
        w.u32(self.id);
        self.cmd.encode(w);
    }

    pub fn decode(r: &mut Reader<'_>) -> Result<Self, DecodeError> {
        let f_id = r.u32()?;
        let f_cmd = Cmd::decode(r)?;
        Ok(Self { id: f_id, cmd: f_cmd })
    }
}

/// What a decoder has received so far in one generation: the entries of every table (ids are positions).
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Tables {
    /// The generation the entries belong to (`None` before the first message).
    pub generation: Option<u32>,
    pub sym: Vec<Vec<u16>>,
    pub faces: Vec<Face>,
    pub images: Vec<Image>,
}

impl Tables {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn clear(&mut self) {
        *self = Self::default();
    }

    /// The number of entries of every table, in declaration order.
    pub fn lens(&self) -> [usize; 3] {
        [self.sym.len(), self.faces.len(), self.images.len()]
    }

    /// Drops the entries past `lens` (a failed message leaves the tables as they were).
    pub fn truncate(&mut self, lens: &[usize; 3]) {
        let [l0, l1, l2] = *lens;
        self.sym.truncate(l0);
        self.faces.truncate(l1);
        self.images.truncate(l2);
    }

    /// The entries past `lens` as the delta that would carry them (the generation is the tables').
    pub fn delta_since(&self, lens: &[usize; 3]) -> Delta {
        let [l0, l1, l2] = *lens;
        Delta {
            generation: self.generation.unwrap_or(0),
            sym: TableDelta { from: u32::try_from(l0).unwrap_or(0), items: self.sym.get(l0..).unwrap_or(&[]).to_vec() },
            faces: TableDelta { from: u32::try_from(l1).unwrap_or(0), items: self.faces.get(l1..).unwrap_or(&[]).to_vec() },
            images: TableDelta { from: u32::try_from(l2).unwrap_or(0), items: self.images.get(l2..).unwrap_or(&[]).to_vec() },
        }
    }

    /// The code units of symbol `id` (empty for an id the table does not have).
    pub fn sym_units(&self, id: u32) -> &[u16] {
        usize::try_from(id).ok().and_then(|i| self.sym.get(i)).map_or(&[], Vec::as_slice)
    }
}

/// The new entries a message carries, per table, and its generation (the encoder's input).
#[derive(Debug, Clone, Default, PartialEq)]
pub struct Delta {
    pub generation: u32,
    pub sym: TableDelta<Vec<u16>>,
    pub faces: TableDelta<Face>,
    pub images: TableDelta<Image>,
}

/// The id and generation of a message, after the magic and the schema hash were checked.
pub fn peek_header(buf: &[u8]) -> Result<uo_codec::Header, DecodeError> {
    Reader::new(buf, &Limits::default()).header(&MAGIC, &SCHEMA_HASH)
}

/// Writes a `Frame` message: the header, the new table entries of `delta`, the body.
/// On an error `out` is left as it was.
pub fn encode_frame(out: &mut Vec<u8>, delta: &Delta, msg: &Frame) -> Result<(), EncodeError> {
    let mut w = Writer::new(out);
    w.header(&MAGIC, &SCHEMA_HASH, MSG_FRAME, delta.generation);
    w.u32(delta.sym.from);
    w.len(delta.sym.items.len());
    w.u32(delta.faces.from);
    w.len(delta.faces.items.len());
    w.u32(delta.images.from);
    w.len(delta.images.items.len());
    for e in delta.sym.items.iter() { w.utf16(e); }
    for e in delta.faces.items.iter() { e.encode(&mut w); }
    for e in delta.images.items.iter() { e.encode(&mut w); }
    msg.encode(&mut w);
    w.finish()
}

/// Reads a `Frame` message. `tables` is the state of this stream of messages: the new entries are
/// appended, a new generation replaces them, and an error leaves them as they were.
pub fn decode_frame(buf: &[u8], tables: &mut Tables, limits: &Limits) -> Result<Frame, DecodeError> {
    let mut r = Reader::new(buf, limits);
    let head = r.header(&MAGIC, &SCHEMA_HASH)?;
    if head.message != MSG_FRAME {
        return Err(DecodeError::WrongMessage { expected: MSG_FRAME, found: head.message });
    }
    let previous = if tables.generation == Some(head.generation) { None } else { Some(std::mem::take(tables)) };
    let lens = tables.lens();
    match decode_frame_body(&mut r, tables) {
        Ok(msg) => {
            tables.generation = Some(head.generation);
            Ok(msg)
        }
        Err(e) => {
            match previous { Some(p) => *tables = p, None => tables.truncate(&lens) }
            Err(e)
        }
    }
}

fn decode_frame_body(r: &mut Reader<'_>, tables: &mut Tables) -> Result<Frame, DecodeError> {
    let n_sym = r.table_header(0, "sym", tables.sym.len(), 8)?;
    let n_faces = r.table_header(1, "faces", tables.faces.len(), 24)?;
    let n_images = r.table_header(2, "images", tables.images.len(), 24)?;
    r.charge_alloc(n_sym, std::mem::size_of::<Vec<u16>>())?; for _ in 0..n_sym { tables.sym.push(r.utf16()?); }
    r.charge_alloc(n_faces, std::mem::size_of::<Face>())?; for _ in 0..n_faces { tables.faces.push(Face::decode(r)?); }
    r.charge_alloc(n_images, std::mem::size_of::<Image>())?; for _ in 0..n_images { tables.images.push(Image::decode(r)?); }
    let msg = Frame::decode(r)?;
    r.end()?;
    Ok(msg)
}

/// Writes a `Command` message: the header, the new table entries of `delta`, the body.
/// On an error `out` is left as it was.
pub fn encode_command(out: &mut Vec<u8>, delta: &Delta, msg: &Command) -> Result<(), EncodeError> {
    let mut w = Writer::new(out);
    w.header(&MAGIC, &SCHEMA_HASH, MSG_COMMAND, delta.generation);
    w.u32(delta.sym.from);
    w.len(delta.sym.items.len());
    w.u32(delta.faces.from);
    w.len(delta.faces.items.len());
    w.u32(delta.images.from);
    w.len(delta.images.items.len());
    for e in delta.sym.items.iter() { w.utf16(e); }
    for e in delta.faces.items.iter() { e.encode(&mut w); }
    for e in delta.images.items.iter() { e.encode(&mut w); }
    msg.encode(&mut w);
    w.finish()
}

/// Reads a `Command` message. `tables` is the state of this stream of messages: the new entries are
/// appended, a new generation replaces them, and an error leaves them as they were.
pub fn decode_command(buf: &[u8], tables: &mut Tables, limits: &Limits) -> Result<Command, DecodeError> {
    let mut r = Reader::new(buf, limits);
    let head = r.header(&MAGIC, &SCHEMA_HASH)?;
    if head.message != MSG_COMMAND {
        return Err(DecodeError::WrongMessage { expected: MSG_COMMAND, found: head.message });
    }
    let previous = if tables.generation == Some(head.generation) { None } else { Some(std::mem::take(tables)) };
    let lens = tables.lens();
    match decode_command_body(&mut r, tables) {
        Ok(msg) => {
            tables.generation = Some(head.generation);
            Ok(msg)
        }
        Err(e) => {
            match previous { Some(p) => *tables = p, None => tables.truncate(&lens) }
            Err(e)
        }
    }
}

fn decode_command_body(r: &mut Reader<'_>, tables: &mut Tables) -> Result<Command, DecodeError> {
    let n_sym = r.table_header(0, "sym", tables.sym.len(), 8)?;
    let n_faces = r.table_header(1, "faces", tables.faces.len(), 24)?;
    let n_images = r.table_header(2, "images", tables.images.len(), 24)?;
    r.charge_alloc(n_sym, std::mem::size_of::<Vec<u16>>())?; for _ in 0..n_sym { tables.sym.push(r.utf16()?); }
    r.charge_alloc(n_faces, std::mem::size_of::<Face>())?; for _ in 0..n_faces { tables.faces.push(Face::decode(r)?); }
    r.charge_alloc(n_images, std::mem::size_of::<Image>())?; for _ in 0..n_images { tables.images.push(Image::decode(r)?); }
    let msg = Command::decode(r)?;
    r.end()?;
    Ok(msg)
}
